-- PRUEBAS DE LAS FUNCIONES DE LA PLATA (FASE 5B)
-- SE EJECUTAN DENTRO DE UNA TRANSACCION Y AL FINAL SE HACE ROLLBACK PARA NO DEJAR DATOS DE PRUEBA
-- ESCENARIO (TODO EN ESTE MES SALVO LO QUE SE DIGA):
--   INGRESOS: LECHE 600.000 (400 L) Y 300.000 (SIN LITROS); OTRO 50.000; VENTA DE LA VACA 31 POR 2.000.000 (DESDE LA SALIDA)
--   GASTOS: DROGAS 120.000; SAL 80.000; JORNALES 400.000; UNA COMPRA DE HACE 2 MESES (FUERA DEL MES) 1.500.000
--   -> ESTE MES: INGRESOS 2.950.000, GASTOS 600.000, SALDO 2.350.000; PRECIO DEL LITRO 1.500 (SOLO CON LA VENTA QUE TRAE LITROS)
BEGIN;

SELECT FUN_CREAR_FINCA_JSON('Finca Prueba', 'San Gil', NULL, NULL, NULL, 'PRU-DUENO', 'Dueño Prueba') ->> 'CODIGO' AS FINCA_200;
CREATE FUNCTION pg_temp.FINCA() RETURNS INTEGER AS $$ SELECT ID_FINCA FROM TAB_FINCAS WHERE NOM_FINCA = 'Finca Prueba' $$ LANGUAGE sql;
CREATE FUNCTION pg_temp.U(jSUFIJO VARCHAR) RETURNS UUID AS $$ SELECT ('00000000-0000-0000-0000-' || lpad(jSUFIJO, 12, '0'))::UUID $$ LANGUAGE sql;
--UN DIA DE ESTE MES QUE NUNCA ES FUTURO (EL 1 A LAS 8)
CREATE FUNCTION pg_temp.MES() RETURNS TIMESTAMP AS $$ SELECT date_trunc('month', CURRENT_DATE) + TIME '08:00' $$ LANGUAGE sql;
CREATE FUNCTION pg_temp.ANOTAR(jSUF VARCHAR, jTIPO VARCHAR, jCAT VARCHAR, jVALOR NUMERIC, jLITROS NUMERIC, jDESC VARCHAR, jFECHA TIMESTAMP, jUSU VARCHAR) RETURNS JSON AS $$
    SELECT FUN_CREAR_MOVIMIENTO_JSON(pg_temp.U(jSUF), pg_temp.FINCA(), jTIPO, jCAT, jVALOR, jLITROS, jDESC, jFECHA, jUSU)
$$ LANGUAGE sql;
CREATE FUNCTION pg_temp.PLATA(jDESDE DATE, jHASTA DATE) RETURNS JSON AS $$ SELECT FUN_OBTENER_PLATA_JSON(pg_temp.FINCA(), 'PRU-DUENO', jDESDE, jHASTA) -> 'DATOS' $$ LANGUAGE sql;
SELECT FUN_AGREGAR_PERSONA_FINCA_JSON(pg_temp.FINCA(), 'PRU-VAQUERO', 'Vaquero Prueba', 'VAQUERO', 'PRU-DUENO') ->> 'CODIGO' AS VAQUERO_200,
       FUN_AGREGAR_PERSONA_FINCA_JSON(pg_temp.FINCA(), 'PRU-VET', 'Veterinaria Prueba', 'VETERINARIO', 'PRU-DUENO') ->> 'CODIGO' AS VET_200;
SELECT FUN_CREAR_ANIMAL_JSON(pg_temp.U('31'), pg_temp.FINCA(), NULL, NULL, '31', NULL, 'H', '2019-01-01', 'SI', NULL, NULL, NULL, 'COMPRADO', (CURRENT_DATE - 400), 'PRU-DUENO') ->> 'CODIGO' AS VACA_200;


SELECT 'PRUEBA 1.1: Anotar. DEBEN SALIR 200 EN LOS 7 Y 200 CON YA_EXISTIA AL REPETIR EL UUID' as PRUEBA;
SELECT pg_temp.ANOTAR('A1', 'INGRESO', 'VENTA_LECHE', 600000, 400, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS LECHE_200,
       pg_temp.ANOTAR('A2', 'INGRESO', 'VENTA_LECHE', 300000, NULL, 'Al vecino', pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS LECHE_SIN_LITROS_200,
       pg_temp.ANOTAR('A3', 'INGRESO', 'OTRO_INGRESO', 50000, NULL, 'Arriendo del potrero', pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS OTRO_200,
       pg_temp.ANOTAR('B1', 'GASTO', 'DROGAS', 120000, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS DROGAS_200,
       pg_temp.ANOTAR('B2', 'GASTO', 'SAL_CONCENTRADO', 80000, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS SAL_200,
       pg_temp.ANOTAR('B3', 'GASTO', 'JORNALES', 400000, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS JORNALES_200,
       pg_temp.ANOTAR('B4', 'GASTO', 'COMPRA_ANIMAL', 1500000, NULL, NULL, pg_temp.MES() - INTERVAL '2 months', 'PRU-DUENO') ->> 'CODIGO' AS COMPRA_200,
       pg_temp.ANOTAR('B1', 'GASTO', 'DROGAS', 120000, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') -> 'DATOS' ->> 'YA_EXISTIA' AS REPETIDO_TRUE;
SELECT FUN_CREAR_SALIDA_JSON(gen_random_uuid(), pg_temp.FINCA(), pg_temp.U('31'), 'VENTA', 2000000, NULL, NULL, pg_temp.MES(), NULL, 'PRU-DUENO') ->> 'CODIGO' AS VENTA_VACA_200;

SELECT 'PRUEBA 1.2: Validaciones. DEBEN SALIR 400: VAQUERO, VETERINARIA, VENTA DE ANIMAL A MANO, CATEGORIA DE OTRO TIPO, VALOR 0, CENTAVOS, LITROS EN UN GASTO, OTRO SIN DESCRIPCION, FECHA FUTURA' as PRUEBA;
SELECT pg_temp.ANOTAR('C1', 'GASTO', 'DROGAS', 1000, NULL, NULL, pg_temp.MES(), 'PRU-VAQUERO') ->> 'CODIGO' AS VAQUERO_400,
       pg_temp.ANOTAR('C2', 'GASTO', 'DROGAS', 1000, NULL, NULL, pg_temp.MES(), 'PRU-VET') ->> 'CODIGO' AS VET_400,
       pg_temp.ANOTAR('C3', 'INGRESO', 'VENTA_ANIMAL', 1000, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'MENSAJE' AS VENTA_A_MANO,
       pg_temp.ANOTAR('C4', 'INGRESO', 'DROGAS', 1000, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS CRUZADA_400,
       pg_temp.ANOTAR('C5', 'GASTO', 'DROGAS', 0, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS CERO_400,
       pg_temp.ANOTAR('C6', 'GASTO', 'DROGAS', 1000.5, NULL, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS CENTAVOS_400,
       pg_temp.ANOTAR('C7', 'GASTO', 'DROGAS', 1000, 10, NULL, pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS LITROS_400,
       pg_temp.ANOTAR('C8', 'GASTO', 'OTRO_GASTO', 1000, NULL, ' ', pg_temp.MES(), 'PRU-DUENO') ->> 'CODIGO' AS OTRO_SIN_DESC_400,
       pg_temp.ANOTAR('C9', 'GASTO', 'DROGAS', 1000, NULL, NULL, LOCALTIMESTAMP + INTERVAL '3 days', 'PRU-DUENO') ->> 'CODIGO' AS FUTURA_400;


SELECT 'PRUEBA 2.1: Resumen de este mes (sin fechas). INGRESOS 2950000, GASTOS 600000, SALDO 2350000; LECHE 900000 CON 400 L A 1500' as PRUEBA;
SELECT pg_temp.PLATA(NULL, NULL) ->> 'INGRESOS' AS INGRESOS, pg_temp.PLATA(NULL, NULL) ->> 'GASTOS' AS GASTOS, pg_temp.PLATA(NULL, NULL) ->> 'SALDO' AS SALDO,
       pg_temp.PLATA(NULL, NULL) -> 'LECHE' ->> 'VALOR' AS LECHE, pg_temp.PLATA(NULL, NULL) -> 'LECHE' ->> 'LITROS' AS LITROS,
       pg_temp.PLATA(NULL, NULL) -> 'LECHE' ->> 'PRECIO_LITRO' AS PRECIO_1500;
SELECT 'PRUEBA 2.2: Por categoría. INGRESOS: VENTA_ANIMAL 2000000, VENTA_LECHE 900000 (2), OTRO_INGRESO 50000; GASTOS: JORNALES 400000, DROGAS 120000, SAL 80000' as PRUEBA;
SELECT E ->> 'TIPO' AS TIPO, E ->> 'CATEGORIA' AS CATEGORIA, E ->> 'VALOR' AS VALOR, E ->> 'CANTIDAD' AS CANTIDAD
FROM json_array_elements(pg_temp.PLATA(NULL, NULL) -> 'POR_CATEGORIA') E;

SELECT 'PRUEBA 2.3: Tres meses: entra la compra. GASTOS 2100000, SALDO 850000 Y 2 MESES EN POR_MES' as PRUEBA;
SELECT pg_temp.PLATA((date_trunc('month', CURRENT_DATE) - INTERVAL '2 months')::DATE, CURRENT_DATE) ->> 'GASTOS' AS GASTOS_2100000,
       pg_temp.PLATA((date_trunc('month', CURRENT_DATE) - INTERVAL '2 months')::DATE, CURRENT_DATE) ->> 'SALDO' AS SALDO_850000,
       json_array_length(pg_temp.PLATA((date_trunc('month', CURRENT_DATE) - INTERVAL '2 months')::DATE, CURRENT_DATE) -> 'POR_MES') AS MESES_2;

SELECT 'PRUEBA 2.4: Acceso y periodo. VAQUERO 400, VETERINARIA 400, FECHAS AL REVES 400, MAS DE 3 AÑOS 400' as PRUEBA;
SELECT FUN_OBTENER_PLATA_JSON(pg_temp.FINCA(), 'PRU-VAQUERO', NULL, NULL) ->> 'CODIGO' AS VAQUERO_400,
       FUN_OBTENER_PLATA_JSON(pg_temp.FINCA(), 'PRU-VET', NULL, NULL) ->> 'CODIGO' AS VET_400,
       FUN_OBTENER_PLATA_JSON(pg_temp.FINCA(), 'PRU-DUENO', CURRENT_DATE, CURRENT_DATE - 1) ->> 'CODIGO' AS AL_REVES_400,
       FUN_OBTENER_PLATA_JSON(pg_temp.FINCA(), 'PRU-DUENO', CURRENT_DATE - 1200, CURRENT_DATE) ->> 'CODIGO' AS LARGO_400;


SELECT 'PRUEBA 3.1: Anular los jornales por la sincronización (el dueño): "1 subido" Y LOS GASTOS DEL MES BAJAN A 200000; EL VAQUERO NO PUEDE (1 rechazado)' as PRUEBA;
SELECT FUN_SINCRONIZAR_REGISTROS_JSON(pg_temp.FINCA(), 'PRU-VAQUERO', json_build_array(
    json_build_object('orden', 1, 'uuid', pg_temp.U('B3'), 'tipo', 'MOVIMIENTO', 'operacion', 'ANULAR', 'datos', '{}'::JSON))) ->> 'MENSAJE' AS VAQUERO_RECHAZADO;
SELECT FUN_SINCRONIZAR_REGISTROS_JSON(pg_temp.FINCA(), 'PRU-DUENO', json_build_array(
    json_build_object('orden', 1, 'uuid', pg_temp.U('B3'), 'tipo', 'MOVIMIENTO', 'operacion', 'ANULAR', 'datos', '{}'::JSON))) ->> 'MENSAJE' AS ANULAR;
SELECT pg_temp.PLATA(NULL, NULL) ->> 'GASTOS' AS GASTOS_200000;

SELECT 'PRUEBA 3.2: Anotar por la sincronización: "1 subido" Y LOS INGRESOS DEL MES SUBEN A 3010000' as PRUEBA;
SELECT FUN_SINCRONIZAR_REGISTROS_JSON(pg_temp.FINCA(), 'PRU-DUENO', json_build_array(
    json_build_object('orden', 1, 'uuid', pg_temp.U('A4'), 'tipo', 'MOVIMIENTO', 'operacion', 'CREAR', 'datos', json_build_object(
        'tipo_movimiento', 'INGRESO', 'categoria_movimiento', 'VENTA_LECHE', 'valor_movimiento', 60000, 'litros_movimiento', 40,
        'descripcion_movimiento', NULL, 'fecha_evento', pg_temp.MES())))) ->> 'MENSAJE' AS SINCRONIZAR;
SELECT pg_temp.PLATA(NULL, NULL) ->> 'INGRESOS' AS INGRESOS_3010000;

SELECT 'PRUEBA 3.3: Al bajar cambios: el dueño recibe 7 movimientos activos; el vaquero y la veterinaria, ninguno' as PRUEBA;
SELECT json_array_length(FUN_OBTENER_CAMBIOS_JSON(pg_temp.FINCA(), 'PRU-DUENO', NULL) -> 'DATOS' -> 'MOVIMIENTOS') AS DUENO_7,
       json_array_length(FUN_OBTENER_CAMBIOS_JSON(pg_temp.FINCA(), 'PRU-VAQUERO', NULL) -> 'DATOS' -> 'MOVIMIENTOS') AS VAQUERO_0,
       json_array_length(FUN_OBTENER_CAMBIOS_JSON(pg_temp.FINCA(), 'PRU-VET', NULL) -> 'DATOS' -> 'MOVIMIENTOS') AS VET_0;

ROLLBACK;
